def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n < 10:
        my_last, op_last = history[-1]
        if op_last == 'D':
            return 'D'
        return 'C'
    opp_def = 0
    my_def = 0
    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1
    recent = history[-10:]
    recent_opp_def = sum(1 for m, o in recent if o == 'D')
    recent_my_def = sum(1 for m, o in recent if m == 'D')
    if recent_opp_def >= 9:
        return 'D'
    if recent_opp_def >= 7:
        return 'D'
    if opp_def * 2 > n:
        if rng.random() < 0.75:
            return 'D'
        return 'C'
    if n >= 20:
        last20 = history[-20:]
        defection_positions = [i for i, (m, o) in enumerate(last20) if o == 'D']
        if defection_positions:
            gap = n - (n - 20 + defection_positions[-1])
            if gap > 0 and rng.random() < 0.05:
                return 'D'
    if recent_opp_def >= 4:
        return 'D'
    consecutive_op_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consecutive_op_def += 1
        else:
            break
    if consecutive_op_def >= 3:
        return 'D'
    if n >= 3:
        m1 = history[-1][0]
        m2 = history[-2][0]
        o1 = history[-1][1]
        o2 = history[-2][1]
        if m1 == 'D' and o1 == 'D' and m2 == 'D':
            return 'D'
    if opp_def == 0 and n >= 15:
        if rng.random() < 0.02:
            return 'D'
        return 'C'
    coop_rate = 1.0 - float(opp_def) / float(n) if n > 0 else 1.0
    if coop_rate > 0.9:
        return 'C'
    if coop_rate > 0.7:
        if rng.random() < 0.9:
            return 'C'
        return 'D'
    if recent_opp_def == 0:
        return 'C'
    return 'D'
